Parse_external_domains_file_+_create_arr.inputs:
@
split(
  replace(
    toLower(
      trim(
        string(outputs('Load_External_Domains')?['body'])
      )
    ),
    decodeUriComponent('%0D'),
    ''
  ),
  decodeUriComponent('%0A')
)

inputs.select:
@concat(
  ',',
  '"',
  replace(coalesce(item()?['ParameterName'], item()?['Title'], ''), '"', concat(decodeUriComponent('%5C'), '"')),
  '":"',
  replace(
    replace(
      replace(
        replace(
          coalesce(
            if(
              equals(variables('CurrentOperationMode'), 'PROD_NODMP'),
              coalesce(item()?['Value_x002d_PROD_x0028_NODMP_x0029'], item()?['Value_PROD_NODMP'], ''),
              if(
                equals(variables('CurrentOperationMode'), 'PROD_DMP'),
                coalesce(item()?['Value_x002d_PROD_x0028_DMP_x0029'], ''),
                if(
                  equals(variables('CurrentOperationMode'), 'SIMU_NODMP'),
                  coalesce(item()?['Value_x002d_SIMU_x0028_NODMP_x0029'], item()?['Value_x002d_SIMU_x0028_NODMP_x00'], ''),
                  coalesce(item()?['Value_x002d_SIMU_x0028_DMP_x0029'], '')
                )
              )
            ),
            ''
          ),
          decodeUriComponent('%5C'),
          concat(decodeUriComponent('%5C'), decodeUriComponent('%5C'))
        ),
        '"',
        concat(decodeUriComponent('%5C'), '"')
      ),
      decodeUriComponent('%0D'),
      ''
    ),
    decodeUriComponent('%0A'),
    concat(decodeUriComponent('%5C'), 'n')
  ),
  '"'
)
